const cfg = $('Set - Gateway Config').first().json;
const result = $input.first().json;
const customers = result.data || [];
const customer = customers[0] || null;

const validRoles = ['admin', 'user', 'readonly'];
const rawRole = (customer?.metadata?.role || '').toLowerCase();
const role = validRoles.includes(rawRole) ? rawRole : 'readonly';

return [{
  json: {
    ...cfg,
    authenticated: !!customer,
    customerId: customer?.id || null,
    role: customer ? role : null
  }
}];

const ctx = $input.first().json;
const allowedRoles = ctx.routePermissions?.[ctx.targetRoute] || null;

const routeExists = !!allowedRoles;
const authorized = routeExists && allowedRoles.includes(ctx.role);

return [{
  json: {
    ...ctx,
    routeExists,
    authorized,
    authorizationReason: !routeExists ? 'unknown_route' : (!authorized ? 'role_not_permitted' : 'ok')
  }
}];

const ctx = $('IF - Authorized').first().json;
const redisResult = $input.first().json;
const currentCount = redisResult.data ?? redisResult.value ?? redisResult ?? 0;

const limit = ctx.rateLimits?.[ctx.role] ?? 60;
const withinLimit = Number(currentCount) <= limit;
const remaining = Math.max(0, limit - Number(currentCount));
const retryAfterSeconds = withinLimit ? 0 : ctx.rateLimitWindowSeconds;

return [{
  json: {
    ...ctx,
    requestCount: Number(currentCount),
    rateLimit: limit,
    rateLimitRemaining: remaining,
    withinRateLimit: withinLimit,
    retryAfterSeconds
  }
}];

const ctx = $input.first().json;
const targetUrl = ctx.internalWorkflowMap?.[ctx.targetRoute] || null;

return [{
  json: {
    ...ctx,
    targetWorkflowUrl: targetUrl
  }
}];

const ctx = $('JS - Resolve Target Workflow').first().json;
const internalResponse = $input.first().json;

return [{
  json: {
    success: true,
    data: internalResponse,
    rateLimit: {
      limit: ctx.rateLimit,
      remaining: ctx.rateLimitRemaining,
      windowSeconds: ctx.rateLimitWindowSeconds
    }
  }
}];
